        D[f'A^{i} t^{j}']=A**i*t**j
for lam in [0.25,0.5,1.0]:
    e=np.exp(-lam*t)
    for i in range(0,4):
        for j in range(0,2):
            D[f'e{lam} A^{i} t^{j}']=e*A**i*t**j
for i in range(-1,3):
